import{_ as o,I as a,o as n,c as d,b6 as i,j as l,J as t,w as c}from"./chunks/framework.BUXTSoD9.js";const y=JSON.parse('{"title":"生鲜电商微服务系统开发实战","description":"","frontmatter":{},"headers":[],"relativePath":"es-es/stage-2/assignments/simple-grocery-microservices/index.md","filePath":"es-es/stage-2/assignments/simple-grocery-microservices/index.md"}'),p={name:"es-es/stage-2/assignments/simple-grocery-microservices/index.md"},h={style:{margin:"32px 0"}};function u(m,e,b,g,f,v){const r=a("StepBar"),s=a("ClientOnly");return n(),d("div",null,[e[0]||(e[0]=i('<h1 id="生鲜电商微服务系统开发实战" tabindex="-1">生鲜电商微服务系统开发实战 <a class="header-anchor" href="#生鲜电商微服务系统开发实战" aria-label="Permalink to “生鲜电商微服务系统开发实战”">​</a></h1><h2 id="descripcion-general" tabindex="-1">Descripcion general <a class="header-anchor" href="#descripcion-general" aria-label="Permalink to “Descripcion general”">​</a></h2><p>Este proyecto practico te requiere trabajar con un PRD real，completar desde cero un生鲜电商微服务系统。与前面的单服务项目不同，这个项目的后端按业务拆分成多个独立服务，通过 API 网关统一对外。你将学习如何设计服务边界、如何处理跨服务的Consistencia de datos问题。</p><p>Esta es la seccion de practica integral de la Etapa 2。微服务架构在实际工作中非常常见，掌握服务拆分和网关路由的基本思路后，你能够应对更复杂的后端系统设计。</p><h2 id="conocimientos-previos" tabindex="-1">Conocimientos previos <a class="header-anchor" href="#conocimientos-previos" aria-label="Permalink to “Conocimientos previos”">​</a></h2><p>Antes de comenzar este proyecto, ya deberias dominar lo siguiente:</p><ul><li>Diseno de paginas frontend y uso de bibliotecas de componentes（<a href="./../../frontend/ui-design/">UI 设计</a>、<a href="./../../frontend/modern-component-library/">现代组件库</a>）</li><li>Diseno y desarrollo de interfaces backend（<a href="./../../backend/ai-interface-code/">接口代码编写</a>）</li><li>Fundamentos de bases de datos y Supabase（<a href="./../../backend/database-supabase/">从数据库到 Supabase</a>）</li><li>Flujo de trabajo de Git y despliegue（<a href="./../../backend/git-workflow/">Git 和 GitHub</a>、<a href="./../../backend/zeabur-deployment/">Despliegue Web 应用</a>）</li></ul><h2 id="objetivos-de-aprendizaje" tabindex="-1">Objetivos de aprendizaje <a class="header-anchor" href="#objetivos-de-aprendizaje" aria-label="Permalink to “Objetivos de aprendizaje”">​</a></h2><p>Despues de completar esta practica, podras:</p><ol><li>Leer el PRD 并提取微服务系统的开发任务清单</li><li>Divir los limites de servicios por dominio de negocio (autenticacion, productos, inventario, ordenes)</li><li>Disenar e implementar el enrutamiento del API Gateway</li><li>Manejar problemas entre servicios como deduccion de inventario y consistencia de ordenes</li><li>Completar la integracion de extremo a extremo, entregando un prototipo de microservicios demostrable</li></ol><h2 id="introduccion-del-proyecto" tabindex="-1">Introduccion del proyecto <a class="header-anchor" href="#introduccion-del-proyecto" aria-label="Permalink to “Introduccion del proyecto”">​</a></h2><p>El producto que vas a construir es一个生鲜电商微服务系统：</p><table tabindex="0"><thead><tr><th>Subsistema</th><th>Responsabilidad</th></tr></thead><tbody><tr><td><strong>Portal de usuario</strong></td><td>Navegar productos, hacer pedidos, ver ordenes</td></tr><tr><td><strong>Portal de administracion</strong></td><td>Gestion de productos, gestion de inventario, gestion de ordenes</td></tr></tbody></table><p>后端按业务拆分为以下服务：</p><table tabindex="0"><thead><tr><th>服务</th><th>Responsabilidad</th></tr></thead><tbody><tr><td><strong>API Gateway</strong></td><td>Entrada unificada, enrutamiento, verificacion de autenticacion</td></tr><tr><td><strong>Auth Service</strong></td><td>Registro de usuarios, login, emision de JWT</td></tr><tr><td><strong>Catalog Service</strong></td><td>Gestion de informacion de productos</td></tr><tr><td><strong>Inventory Service</strong></td><td>Gestion de cantidades de inventario</td></tr><tr><td><strong>Order Service</strong></td><td>Creacion de ordenes, gestion de estados</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">PRD 入口</p><p>El documento de requisitos de este proyecto esta en GitHub： <a href="https://github.com/datawhalechina/easy-vibe/blob/main/docs/es-es/stage-2/assignments/simple-grocery-microservices/PRD.md" target="_blank" rel="noreferrer">Ver PRD</a></p></div>',16)),l("div",h,[t(s,null,{default:c(()=>[t(r,{active:0,items:[{title:"Analisis de requisitos",description:"Leer el PRD，明确服务拆分、页面和交易链路"},{title:"Construccion del esqueleto",description:"生成前端、网关和各服务骨架"},{title:"Desarrollo iterativo",description:"逐模块补接口、修库存与订单一致性"},{title:"Integracion y despliegue",description:"Verificar de extremo a extremo，Desplegar y preparar la demostracion"}]})]),_:1})]),e[1]||(e[1]=i(`<h2 id="primera-parte-analisis-de-requisitos" tabindex="-1">Primera parte：Analisis de requisitos <a class="header-anchor" href="#primera-parte-analisis-de-requisitos" aria-label="Permalink to “Primera parte：Analisis de requisitos”">​</a></h2><h3 id="_1-1-leer-el-prd" tabindex="-1">1.1 Leer el PRD <a class="header-anchor" href="#_1-1-leer-el-prd" aria-label="Permalink to “1.1 Leer el PRD”">​</a></h3><p>打开 PRD 文档，重点回答以下问题：</p><ul><li>服务如何拆分？每个服务的Responsabilidad边界是什么？</li><li>前台和Portal de administracion分别有哪些页面？</li><li>下单后库存扣减的策略是什么？成功 / 失败 / 超时各怎么处理？</li><li>第一版哪些复杂能力（如分布式事务、消息队列）先不做？</li></ul><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>Si no tienes respuestas claras a las preguntas anteriores, no comiences a escribir codigo. La comprension inadecuada de los requisitos es la causa mas comun de retrabajo.</p></div><h3 id="_1-2-confirmar-la-arquitectura-del-sistema" tabindex="-1">1.2 Confirmar la arquitectura del sistema <a class="header-anchor" href="#_1-2-confirmar-la-arquitectura-del-sistema" aria-label="Permalink to “1.2 Confirmar la arquitectura del sistema”">​</a></h3><div class="language-mermaid"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prd[&quot;PRD&quot;] --&gt; fe[&quot;前端页面&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  fe --&gt; gw[&quot;API Gateway&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  gw --&gt; auth[&quot;Auth Service&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  gw --&gt; catalog[&quot;Catalog Service&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  gw --&gt; inventory[&quot;Inventory Service&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  gw --&gt; order[&quot;Order Service&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  order --&gt; inventory</span></span></code></pre></div><h2 id="segunda-parte-搭建项目骨架" tabindex="-1">Segunda parte：搭建项目骨架 <a class="header-anchor" href="#segunda-parte-搭建项目骨架" aria-label="Permalink to “Segunda parte：搭建项目骨架”">​</a></h2><h3 id="_2-1-生成项目结构" tabindex="-1">2.1 生成项目结构 <a class="header-anchor" href="#_2-1-生成项目结构" aria-label="Permalink to “2.1 生成项目结构”">​</a></h3><p>Referencia de prompts：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>请基于当前 PRD，帮我生成一个生鲜电商微服务系统的项目骨架。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>要求：</span></span>
<span class="line"><span>1. 生成前端Portal de usuario和Portal de administracion骨架</span></span>
<span class="line"><span>2. 生成 api-gateway、auth-service、catalog-service、inventory-service、order-service 五个目录</span></span>
<span class="line"><span>3. 每个服务先只做最小可运行入口</span></span>
<span class="line"><span>4. 先不接真实数据库和支付</span></span></code></pre></div><h3 id="_2-2-验证项目结构" tabindex="-1">2.2 验证项目结构 <a class="header-anchor" href="#_2-2-验证项目结构" aria-label="Permalink to “2.2 验证项目结构”">​</a></h3><p>Verificar item por item:</p><ul><li>[ ] 五个服务目录结构清晰</li><li>[ ] API Gateway 可以启动并转发请求</li><li>[ ] 各服务健康检查接口可用</li><li>[ ] 前端Portal de usuario和Portal de administracion页面可访问</li></ul><h2 id="tercera-parte-desarrollo-iterativo" tabindex="-1">Tercera parte：Desarrollo iterativo <a class="header-anchor" href="#tercera-parte-desarrollo-iterativo" aria-label="Permalink to “Tercera parte：Desarrollo iterativo”">​</a></h2><h3 id="_3-1-avanzar-por-modulos" tabindex="-1">3.1 Avanzar por modulos <a class="header-anchor" href="#_3-1-avanzar-por-modulos" aria-label="Permalink to “3.1 Avanzar por modulos”">​</a></h3><ol><li><strong>API Gateway</strong>：路由配置、JWT 校验中间件</li><li><strong>Auth Service</strong>：注册、登录、JWT 颁发</li><li><strong>Catalog Service</strong>：商品 CRUD、列表查询</li><li><strong>Inventory Service</strong>：库存查询、库存扣减</li><li><strong>Order Service</strong>：订单创建、状态流转、库存联动</li><li><strong>Portal de administracion</strong>：Gestion de productos, gestion de inventario, gestion de ordenes</li></ol><h3 id="_3-2-autoverificacion-de-modulos" tabindex="-1">3.2 Autoverificacion de modulos <a class="header-anchor" href="#_3-2-autoverificacion-de-modulos" aria-label="Permalink to “3.2 Autoverificacion de modulos”">​</a></h3><table tabindex="0"><thead><tr><th>Item de verificacion</th><th>Metodo de verificacion</th></tr></thead><tbody><tr><td>网关路由</td><td>各服务接口是否通过网关正确转发</td></tr><tr><td>Aislamiento de permisos</td><td>Portal de usuario和Portal de administracion接口是否隔离</td></tr><tr><td>数据一致</td><td>商品和库存数据是否同步</td></tr><tr><td>交易闭环</td><td>下单后库存扣减、订单状态是否一致</td></tr><tr><td>失败处理</td><td>库存不足或超时时是否有补偿机制</td></tr></tbody></table><h2 id="cuarta-parte-联调与上线" tabindex="-1">Cuarta parte：联调与上线 <a class="header-anchor" href="#cuarta-parte-联调与上线" aria-label="Permalink to “Cuarta parte：联调与上线”">​</a></h2><h3 id="_4-1-pruebas-de-extremo-a-extremo" tabindex="-1">4.1 Pruebas de extremo a extremo <a class="header-anchor" href="#_4-1-pruebas-de-extremo-a-extremo" aria-label="Permalink to “4.1 Pruebas de extremo a extremo”">​</a></h3><p>Verificar al menos los siguientes escenarios:</p><ul><li>浏览商品 → 加入购物车 → 下单 → 查看订单</li><li>管理员 → 添加商品 → 更新库存 → 查看订单</li></ul><h2 id="entregables" tabindex="-1">Entregables <a class="header-anchor" href="#entregables" aria-label="Permalink to “Entregables”">​</a></h2><p>Despues de completar este proyecto, necesitas enviar lo siguiente:</p><ul><li>[ ] Enlace de demostracion en linea accesible</li><li>[ ] Enlace al repositorio de codigo fuente (incluyendo README)</li><li>[ ] PRD 文档</li><li>[ ] Capturas de pantalla de paginas clave（商品列表、下单页、订单页、Panel de administracion）</li><li>[ ] 60 segundos de video de demostracion</li></ul><h2 id="criterios-de-evaluacion" tabindex="-1">Criterios de evaluacion <a class="header-anchor" href="#criterios-de-evaluacion" aria-label="Permalink to “Criterios de evaluacion”">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>Requisitos basicos</th><th>Requisitos avanzados</th></tr></thead><tbody><tr><td>Alineacion con PRD</td><td>页面、功能、服务拆分基本符合 PRD</td><td>能清晰说明服务拆分的理由</td></tr><tr><td>Ciclo completo del producto</td><td>浏览 → 下单 → 库存扣减 → 查看订单可跑通</td><td>订单超时或库存不足有补偿机制</td></tr><tr><td>服务架构</td><td>各服务可独立启动，通过网关统一访问</td><td>服务间通信有错误处理和重试</td></tr><tr><td>Capacidades del backend</td><td>商品、库存、订单管理可操作</td><td>Portal de administracion有数据统计</td></tr><tr><td>Completitud de ingenieria</td><td>前端、网关、服务、数据库链路已接通</td><td>有 Docker Compose 或类似编排</td></tr></tbody></table><h2 id="referencias" tabindex="-1">Referencias <a class="header-anchor" href="#referencias" aria-label="Permalink to “Referencias”">​</a></h2><ul><li><a href="./../../frontend/ui-design/">UI 设计</a></li><li><a href="./../../frontend/modern-component-library/">使用现代组件库更新你的界面</a></li><li><a href="./../../backend/database-supabase/">从数据库到 Supabase</a></li><li><a href="./../../backend/ai-interface-code/">大模型辅助编写接口代码与接口文档</a></li><li><a href="./../../backend/git-workflow/">Git 和 GitHub 工作流</a></li><li><a href="./../../backend/zeabur-deployment/">如何Despliegue Web 应用</a></li></ul>`,30))])}const P=o(p,[["render",u]]);export{y as __pageData,P as default};
